"""Simple job scheduler for periodic ingestion tasks."""

import time
import logging
import traceback

logger = logging.getLogger(__name__)


class Job:
    def __init__(self, name, fn, interval_seconds, args=None, kwargs=None):
        self.name = name
        self.fn = fn
        self.interval = interval_seconds
        self.args = args or ()
        self.kwargs = kwargs or {}
        self.last_run = 0
        self.run_count = 0
        self.error_count = 0
        self.last_error = None
        self.enabled = True

    def is_due(self):
        return self.enabled and (time.time() - self.last_run) >= self.interval

    def execute(self):
        self.last_run = time.time()
        self.run_count += 1
        try:
            result = self.fn(*self.args, **self.kwargs)
            return result
        except Exception as exc:
            self.error_count += 1
            self.last_error = str(exc)
            logger.error(f"Job '{self.name}' failed: {exc}\n{traceback.format_exc()}")
            return None

    def status(self):
        return {
            "name": self.name,
            "interval": self.interval,
            "last_run": self.last_run,
            "run_count": self.run_count,
